const c = $('Contexto da licitação').first().json;
const pedido = $('Chamado pelo W20/W30').first().json;
let motivo;
if (!c.controle) motivo = 'W24: licitação não existe';
else if (c.modo === 'republicar' && !c.pedida_e_desta) motivo = `W24 republicar: a verificação ${pedido.verificacao_id} não é desta licitação`;
else if (c.modo === 'republicar') motivo = `W24 republicar: estado ${c.estado} não é publicada nem verificada`;
else motivo = `W24: estado ${c.estado} não tem o que verificar nem publicar`;
return [{ json: { ok: false, continuar: false, modo: c.modo || 'publicar', estado: c.estado ?? null,
  controle: pedido.controle, motivo } }];

// regra — só as APROVADAS com trecho vão ao Jev: é nelas que mora o ponto cego da ancoragem (api/rotas_jev.py:63-95)
const b = $input.first().json.body;
return b.requisicoes.map((r) => ({ json: { url: b.url, body: r.body, pergunta_id: r.pergunta_id,
  contexto_enviado: r.contexto_enviado, criterio_versao: b.criterio_versao } }));

// O Jev é segundo sinal, nunca decisão (T25): o veredito não muda; convicção contrária vira candidata na fila humana
// (quem grava é o worker, api/rotas_jev.py:98-119). Aqui só se conta o que aconteceu.
const itens = $input.all().map((i) => (i.json && i.json.body) || {});
return [{ json: { jev: {
  perguntas: itens.length,
  sinais: itens.filter((s) => s.sinal_id).length,
  candidatas: itens.filter((s) => s.candidata === true).length,
  usd: itens.reduce((t, s) => t + (Number(s.usd) || 0), 0),
} } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const quando = (iso, temHora) => {
  if (!iso) return 'sem data';
  const d = new Date(iso);
  const tz = 'America/Sao_Paulo';
  return temHora === false
    ? d.toLocaleDateString('pt-BR', { timeZone: tz })
    : d.toLocaleString('pt-BR', { timeZone: tz, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
};
const site = String($env.FOPA_SITE_PUBLIC_URL || '').replace(/\/+$/, '');
const n8nBase = String($env.WEBHOOK_URL || '').replace(/\/+$/, '');
const linkExecucao = `${n8nBase}/workflow/${$workflow.id}/executions/${$execution.id}`;
// regra — e-mail "processada" (plano §2 Alertas; §5 W24 passo 7) ou "republicada" (W30: só as regras mudaram, com o
// diff de vereditos): custo null → "n/d", nunca R$ 0,00 (ADR-012, scripts/fopa/saida.py:169-173); tabela das 17 com
// "arquivo p. N" linkando /api/pdf/{slug}/{arquivo_id}#page=N (ADR-005: página física).
const v = $input.first().json;
const republicar = $('Contexto da licitação').first().json.modo === 'republicar';
const d = republicar ? $('Diff contra a vigente').first().json : null;
const onde = `${v.municipio || v.orgao || v.controle}/${v.uf || '—'}`;
const brl = (v.preco_conhecido === false || v.brl == null) ? 'n/d'
  : Number(v.brl).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const simulado = ['simulado', 'gravado'].includes(v.origem);
const ensaio = simulado ? ` · ENSAIO (${v.origem}, sem modelo pago)` : '';
const mudaram = d ? Object.keys(d.vereditos || {}) : [];
const assunto = republicar
  ? `[FOPA] Republicada: ${onde} · ${mudaram.length} veredito(s) mudaram · regras ${String(v.versao_regras || '').slice(0, 12)}${ensaio}`
  : `[FOPA] Processada: ${onde} · ${v.ancoradas}/${v.respondidas} ancoradas · R$ ${brl}${ensaio}`;
const cor = { APROVADO: '#0a7d5a', REVISAR: '#b26b00', REPROVADO: '#b3261e' };
const vd = (x) => x ? `<span style="color:${cor[x] || '#333'}"><b>${esc(x)}</b></span>` : '—';
const linhas = (v.respostas || []).map((r) => {
  const pdf = (r.arquivo_id && r.pagina)
    ? `<a href="${esc(site)}/api/pdf/${esc(v.slug)}/${r.arquivo_id}#page=${r.pagina}">${esc(r.arquivo || 'arquivo')} p. ${r.pagina}</a>`
    : (r.pagina ? `${esc(r.arquivo || '')} p. ${r.pagina}` : '—');
  return `<tr><td>${esc(r.id)}${r.critico ? ' *' : ''}</td><td>${esc(r.texto)}</td><td>${vd(r.veredito)}</td>`
    + `<td>${esc(r.resposta || '')}</td><td>${pdf}</td></tr>`;
}).join('');
const lista = (xs) => xs.map((a) => `<li>${esc(a)}</li>`).join('');
const tags = (v.tags || []).map((t) => `<code>${esc(t)}</code>`).join(' ');
const blocoDiff = !d ? '' : [
  `<p>Reverificação sem modelo e sem OCR novo (ADR-011): as mesmas respostas, regras ${esc(String(d.versao_regras_antes || '—').slice(0, 20))}`
    + ` → ${esc(String(d.versao_regras || '').slice(0, 20))}. Vigente antes: ${esc(d.antes_id ?? '—')}; agora: ${esc(d.depois_id)}.</p>`,
  mudaram.length
    ? `<table border="1" cellpadding="4" cellspacing="0"><tr><th>#</th><th>Antes</th><th>Depois</th></tr>`
      + mudaram.map((q) => `<tr><td>${esc(q)}</td><td>${vd(d.vereditos[q][0])}</td><td>${vd(d.vereditos[q][1])}</td></tr>`).join('')
      + `</table>`
    : '<p>Nenhum veredito mudou.</p>',
  (d.alertas_entraram || []).length ? `<p>Alertas que entraram:</p><ul>${lista(d.alertas_entraram)}</ul>` : '',
  (d.alertas_sairam || []).length ? `<p>Alertas que saíram:</p><ul>${lista(d.alertas_sairam)}</ul>` : '',
].join('');
const corpo = [
  `<p><b>${esc(v.orgao || '')}</b> — ${esc(onde)} · ${esc(v.modalidade || '')} · controle ${esc(v.controle)}`
    + ` · sessão ${esc(quando(v.fim_prazo, v.fim_prazo_tem_hora))}</p>`,
  `<p>${esc(v.objeto || '')}</p>`,
  simulado ? `<p><b>Ensaio:</b> respostas do provedor ${esc(v.origem)} (sem modelo pago); vale para ver o fluxo, não o edital.</p>` : '',
  blocoDiff,
  `<p>${v.aprovadas} aprovada(s), ${v.revisar} para revisar, ${v.reprovadas} reprovada(s), ${v.nao_localizado} não localizada(s)`
    + ` · ${v.ancoradas}/${v.respondidas} ancoradas · custo R$ ${brl} (${esc(v.provedor || '')} ${esc(v.modelo || '')})`
    + (v.revisoes_abertas > 0 ? ` · <b>${v.revisoes_abertas} revisão(ões) humana(s) aberta(s)</b>` : '') + '</p>',
  (v.alertas_globais || []).length ? `<p>Alertas globais:</p><ul>${lista(v.alertas_globais)}</ul>` : '',
  tags ? `<p>Tags: ${tags}</p>` : '',
  `<table border="1" cellpadding="4" cellspacing="0"><tr><th>#</th><th>Pergunta</th><th>Veredito</th><th>Resposta</th><th>Evidência</th></tr>${linhas}</table>`,
  `<p>* pergunta crítica</p>`,
  `<p><a href="${esc(site)}/licitacao/${esc(v.slug)}">Abrir no site</a> · `
    + `<a href="${esc(site)}/licitacao/${esc(v.slug)}/relatorio">RELATORIO</a> · `
    + `<a href="${esc(linkExecucao)}">execução ${esc($execution.id)} no n8n</a></p>`,
].join('');
return [{ json: { tipo: republicar ? 'republicada' : 'processada', controle: v.controle,
  verificacao_id: v.verificacao_id, assunto, corpo_html: corpo,
  brl: brl === 'n/d' ? null : Number(v.brl), revisoes_abertas: Number(v.revisoes_abertas),
  resumo: { aprovadas: v.aprovadas, revisar: v.revisar, reprovadas: v.reprovadas, ancoradas: v.ancoradas,
            respondidas: v.respondidas, tags: v.tags || [] } } }];

const m = $('Montar e-mail').first().json;
const c = $('Contexto da licitação').first().json;
const d = c.modo === 'republicar' ? $('Diff contra a vigente').first().json : null;
const jev = $('Resumo do Jev').isExecuted ? $('Resumo do Jev').first().json.jev : null;
return [{ json: { ok: true, continuar: false, modo: c.modo, estado: 'publicada', controle: c.controle,
  verificacao_id: m.verificacao_id, html_uri: $('POST /render').first().json.body.html_uri,
  brl: m.brl, revisoes_abertas: m.revisoes_abertas, resumo: m.resumo,
  email_id: $('Enfileirar e-mail').first().json.email_id ?? null, email_tipo: m.tipo,
  antes_verificacao_id: d ? d.antes_id : null,
  diff: d ? { vereditos: d.vereditos || {}, alertas_entraram: d.alertas_entraram || [], alertas_sairam: d.alertas_sairam || [] } : null,
  jev,
  motivo: `W24: ${d ? 'republicada' : 'publicada'} a verificação ${m.verificacao_id}`
    + (d ? ` (${Object.keys(d.vereditos || {}).length} veredito(s) mudaram)` : ` (${m.resumo.ancoradas}/${m.resumo.respondidas} ancoradas)`) } }];

// Falha vira MOTIVO escrito, nunca silêncio. O estado NÃO recua: se /verificar falhou fica `respondida`;
// se o render ou a vigência falharam fica `verificada` e a próxima rodada do W20 republica (plano §5 W24 passo 9).
const j = $input.first().json || {};
let etapa = 'verificar';
if ($('Tornar vigente').isExecuted) etapa = 'tornar vigente';
else if ($('POST /render').isExecuted) etapa = 'render';
let motivo;
if (j.error) motivo = String(j.error.message || j.error.description || JSON.stringify(j.error)).slice(0, 300);
else if (j.statusCode) motivo = `HTTP ${j.statusCode}: ` + (typeof j.body === 'string' ? j.body : JSON.stringify(j.body ?? '')).slice(0, 300);
else motivo = JSON.stringify(j).slice(0, 300);
return [{ json: { motivo: `W24 (${etapa}): ${motivo}` } }];

const c = $('Contexto da licitação').first().json;
const fica = ($('POST /render').isExecuted || c.modo === 'republicar') ? 'verificada' : c.estado;
return [{ json: { ok: false, continuar: false, modo: c.modo, estado: fica, controle: c.controle,
  motivo: $('Motivo da falha').first().json.motivo } }];
